prts.feedbackvariables:
a1:radcan(ans1);
a2:radcan(ans2);
lx1:limit(a1,t,0);
ly1:limit(a2,t,0);
p1approach:numberp(lx1) and numberp(ly1) and is(equal(lx1,0)) and is(equal(ly1,0));
p1zero:if freeof(t,a1) and freeof(t,a2)
       then is(equal(a1,0)) and is(equal(a2,0))
       else false;
p1ok:p1approach and not p1zero;
pathexpr1:radcan(subst([x=a1,y=a2],f));
calc1:limit(pathexpr1,t,0);
finite1:not member(calc1,[inf,minf,und,ind]);
lim1ok:p1ok and finite1 and is(equal(radcan(calc1-ans3),0));
b1:radcan(ans4);
b2:radcan(ans5);
lx2:limit(b1,t,0);
ly2:limit(b2,t,0);
p2approach:numberp(lx2) and numberp(ly2) and is(equal(lx2,0)) and is(equal(ly2,0));
p2zero:if freeof(t,b1) and freeof(t,b2)
       then is(equal(b1,0)) and is(equal(b2,0))
       else false;
p2ok:p2approach and not p2zero;
pathexpr2:radcan(subst([x=b1,y=b2],f));
calc2:limit(pathexpr2,t,0);
finite2:not member(calc2,[inf,minf,und,ind]);
lim2ok:p2ok and finite2 and is(equal(radcan(calc2-ans6),0));
limitsame:is(equal(radcan(calc1-calc2),0));
difflimok:lim1ok and lim2ok and not limitsame;

